def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    # Validate nanoseconds input
    try:
        ns = int(nanoseconds)
    except Exception as exc:
        raise TypeError("nanoseconds must be an integer-like value") from exc

    if ns < 0:
        raise ValueError("nanoseconds must be non-negative")

    # Normalize to a single day (seconds in a day * 10^9 nanoseconds)
    ns_in_day = 24 * 60 * 60 * 1_000_000_000
    ns = ns % ns_in_day

    # Compute hour, minute, second, microsecond
    seconds, remaining_ns = divmod(ns, 1_000_000_000)
    hours, rem = divmod(seconds, 3600)
    minutes, seconds = divmod(rem, 60)
    microseconds = remaining_ns // 1_000

    # Construct the time object
    try:
        if tz is not None:
            # Accept any tzinfo implementation
            if not isinstance(tz, (type(None), datetime.tzinfo)):
                raise TypeError("tz must be a datetime.tzinfo instance or None")
            return datetime.time(
                hour=hours,
                minute=minutes,
                second=seconds,
                microsecond=microseconds,
                tzinfo=tz
            )
        else:
            return datetime.time(
                hour=hours,
                minute=minutes,
                second=seconds,
                microsecond=microseconds
            )
    except Exception as exc:
        raise ValueError("Failed to create time object with provided parameters") from exc

def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    import datetime

    # Validate nanoseconds
    if nanoseconds is None:
        raise ValueError("nanoseconds argument is required")
    try:
        ns = int(nanoseconds)
    except Exception:
        raise TypeError("nanoseconds must be an integer or convertible to int")
    if ns < 0:
        raise ValueError("nanoseconds cannot be negative")

    # Convert nanoseconds to seconds and microseconds
    seconds, nano_remainder = divmod(ns, 1_000_000_000)
    microseconds = nano_remainder // 1_000  # drop the remaining nanoseconds

    # Build datetime instance (UTC by default)
    try:
        base_datetime = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        dt = base_datetime + datetime.timedelta(seconds=seconds, microseconds=microseconds)
    except Exception as exc:
        raise ValueError(f"Failed to construct datetime from nanoseconds: {exc}") from exc

    # Apply timezone if provided
    if tz is not None:
        if not isinstance(tz, datetime.tzinfo):
            raise TypeError("tz must be a datetime.tzinfo instance or None")
        dt = dt.astimezone(tz)

    # Return only the time component
    return dt.time()

