def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    # Handle None explicitly
    if value is None:
        return None

    # Ensure the value looks like a time object that can be converted to an ISO‑format string
    if hasattr(value, "isoformat") and callable(value.isoformat):
        try:
            # .isoformat() gives a suitable dehydrated representation
            return value.isoformat()
        except Exception as exc:
            raise ValueError(f"Unable to format time value {value!r}: {exc}") from exc

    # As a fallback, check for attributes that are typical of time objects
    if (
        hasattr(value, "hour")
        and hasattr(value, "minute")
        and hasattr(value, "second")
        and hasattr(value, "microsecond")
    ):
        # Format manually to avoid depending on a specific library implementation
        try:
            hour = f"{int(value.hour):02d}"
            minute = f"{int(value.minute):02d}"
            second = f"{int(value.second):02d}"
            micro = int(value.microsecond)
            if micro:
                return f"{hour}:{minute}:{second}.{micro:06d}"
            else:
                return f"{hour}:{minute}:{second}"
        except Exception as exc:
            raise ValueError(f"Invalid time components in {value!r}: {exc}") from exc

    raise TypeError(
        f"Expected a time-like object for dehydration, got {type(value).__name__}"
    )

