def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return: str or None
    """
    # None -> None
    if value is None:
        return None

    # Accept string input
    if isinstance(value, str):
        return value

    # Try using standard datetime.time if possible
    try:
        import datetime
        datetime_time = datetime.time
    except Exception:  # pragma: no cover
        datetime_time = None

    if datetime_time and isinstance(value, datetime_time):
        return value.isoformat()

    # Try using a custom to_isoformat() method
    if hasattr(value, "to_isoformat") and callable(value.to_isoformat):
        try:
            rv = value.to_isoformat()
            if isinstance(rv, str):
                return rv
        except Exception:
            pass

    # Pull out common attributes
    try:
        hour = getattr(value, "hour")
        minute = getattr(value, "minute")
        second = getattr(value, "second")
    except AttributeError:
        raise TypeError(f"Cannot dehydrate value of type {type(value).__name__}")

    # Optional sub-second values (millisecond, microsecond, nanosecond)
    frac = None
    if hasattr(value, "millisecond"):
        ms = getattr(value, "millisecond")
        if ms is not None:
            frac = f"{int(ms):03d}"
    if not frac and hasattr(value, "microsecond"):
        us = getattr(value, "microsecond")
        if us is not None:
            frac = f"{int(us//1000):03d}"  # convert µs to ms
    if not frac and hasattr(value, "nanosecond"):
        ns = getattr(value, "nanosecond")
        if ns is not None:
            frac = f"{int(ns//1000000):03d}"  # convert ns to ms

    # Construct string
    ts = f"{int(hour):02d}:{int(minute):02d}:{int(second):02d}"
    if frac:
        ts += f".{frac}"
    return ts

