    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        raise TypeError("`value` is None; expected a Point instance or coordinate sequence")

    # Allow simple tuple/list of coordinates
    if isinstance(value, (list, tuple)) and len(value) >= 2:
        try:
            x = value[0]
            y = value[1]
            z = value[2] if len(value) >= 3 else None
            result = {'x': x, 'y': y}
