        """Remove the last two bytes of data, returning them as a big-endian
        16-bit unsigned integer.
        """
        # Ensure the data attribute exists
        if not hasattr(self, "data"):
            raise AttributeError("Missing 'data' attribute")
        # Convert to a sequence of bytes if necessary
        data = self.data
        # Minimum length check
        try:
            length = len(data)
        except TypeError:
            raise TypeError("'data' must be a byte-like sequence")
        if length < 2:
            raise ValueError("Cannot pop u16: data contains fewer than 2 bytes")
        # Handle mutable types (bytearray, list)
        if isinstance(data, (bytearray, list)):
            val = (data[-2] << 8) + data[-1]
            del data[-2:]
        elif isinstance(data, bytes):
            val = int.from_bytes(data[-2:], "big")
            self.data = data[:-2]
        else:
            # Fallback: attempt pop operations
            try:
                val = (data.pop(-2) << 8) + data.pop(-1)
            except Exception as exc:
                raise TypeError(f"Unsupported data type for pop_u16: {type(data)}") from exc
        return val

