def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """
    Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os
    import shlex

    # Empty or missing tuple handling
    if not cmd:
        return tuple()

    # Convert to list for easier manipulation
    cmd_list = list(cmd)

    # Windows bug 8557: remove leading empty strings that can appear from
    # certain command launching methods
    while cmd_list and cmd_list[0] == '':
        cmd_list.pop(0)

    if not cmd_list:
        return tuple()

    first = cmd_list[0]

    # Check whether the first argument is a script file that contains a shebang
    if os.path.isfile(first):
        try:
            with open(first, 'r', encoding='utf-8', errors='replace') as f:
                first_line = f.readline()
        except Exception:
            # If the file cannot be read, just return the original command
            return tuple(cmd_list)
        else:
            if first_line.startswith('#!'):
                # Extract the interpreter command from the shebang line
                shebang = first_line[2:].strip()
                if shebang:
                    # Split the shebang into the interpreter and its arguments
                    # Using shlex.split ensures that quoted strings are respected
                    parts = shlex.split(shebang)
                    if parts:
                        interpreter = parts[0]
                        # Resolve a relative interpreter path relative to the script
                        if not os.path.isabs(interpreter):
                            script_dir = os.path.dirname(os.path.abspath(first))
                            interpreter = os.path.abspath(os.path.join(script_dir, interpreter))

                        # Build the new command tuple:
                        #   interpreter, script_path (absolute), any shebang args, original args after script
                        new_cmd = [interpreter,
                                   os.path.abspath(first)] + parts[1:] + cmd_list[1:]
                        return tuple(new_cmd)

    # No special handling required; return the original command unchanged
    return tuple(cmd_list)

