    def decorating_function(user_function):
        cache = {}
        order = []  # keeps keys in LRU order: oldest first, newest last
        hits = misses = 0

        def make_key(*args, **kwargs):
            key = args
            if kwargs:
                # kwargs are sorted for deterministic ordering
                key += tuple(sorted(kwargs.items()))
            if typed:
                # include the argument types in the key
