    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        import traceback
        import os

        def shorten_path(path):
            """Return path composed of the last `max_path_level` components."""
            if not isinstance(path, str):
                return str(path)
            parts = path.split(os.sep)
            if len(parts) > max_path_level:
                return os.sep.join(parts[-max_path_level:])
            return path

        # Build a human‑readable representation of the exception
        lines = []

        # Primary exception message
        try:
            lines.append(f"{e.__class__.__name__}: {e}")
        except Exception:
            lines.append(f"{e.__class__.__name__}: <unavailable message>")

        # Function to format a traceback from a given exception
        def format_tb(exc):
            tb = getattr(exc, "__traceback__", None)
            if not tb:
                return
            # Extract stack frames and limit the depth
            frames = traceback.extract_tb(tb)
            if max_level is not None:
                frames = frames[-max_level:]
            lines.append("Traceback (most recent call last):")
            for frame in frames:
                short_file = shorten_path(frame.filename)
                lines.append(f'  File "{short_file}", line {frame.lineno}, in {frame.name}')
                if frame.line:
                    lines.append(f"    {frame.line.strip()}")

        # Primary traceback
        format_tb(e)

        # If the exception was caused by another, display the chain
        cause = getattr(e, "__cause__", None)
        while cause:
            try:
                lines.append("During handling of the above exception, another exception occurred:")
                lines.append(f"{cause.__class__.__name__}: {cause}")
            except Exception:
                lines.append(f"{cause.__class__.__name__}: <unavailable message>")
            format_tb(cause)
            cause = getattr(cause, "__cause__", None)

        return "\n".join(lines)

