@classmethod
    def _reset_logging(cls):
        """
        Reset
        """
        # Retrieve the logger associated with this class; if the class defines its own logger attribute,
        # use that instead of a generic one.
        logger = getattr(cls, '_log', None)
        if logger is None:
            logger = logging.getLogger(cls.__name__)

        # Remove and close all handlers attached to the logger
        handlers = list(logger.handlers)  # copy to avoid modification during iteration
        for h in handlers:
            try:
                logger.removeHandler(h)
            except Exception:
                pass
            try:
                h.close()
            except Exception:
                pass

        # Reset logger level to the default for fresh start
        logger.setLevel(logging.WARNING)  # or None to inherit root level
        # Ensure the logger has at least one handler to avoid "No handler found" warnings
        if not logger.handlers:
            default_handler = logging.StreamHandler()
            default_handler.setFormatter(logging.Formatter('%(levelname)s:%(name)s:%(message)s'))
            logger.addHandler(default_handler)

