def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.
    """
    from collections import defaultdict

    if not orderings:
        return []

    # Collect all unique elements
    elements = set()
    for o in orderings:
        elements.update(o)

    # Build precedence graph: a->b means a must come before b
    successors = defaultdict(set)
    predecessors = defaultdict(set)
    for ordering in orderings:
        n = len(ordering)
        for i in range(n):
            a = ordering[i]
            for j in range(i + 1, n):
                b = ordering[j]
                if b not in successors[a]:
                    successors[a].add(b)
                    predecessors[b].add(a)

    # Compute indegree for each element
    indegree = {e: len(predecessors[e]) for e in elements}

    # Priority for deterministic ordering: order of first appearance
    priority = {}
    counter = 0
    seen = set()
    for ordering in orderings:
        for e in ordering:
            if e not in seen:
                priority[e] = counter
                counter += 1
                seen.add(e)

    # Kahn's algorithm with priority
    result = []
    # start with nodes of zero indegree, sorted by priority
    queue = sorted(
        [e for e in elements if indegree[e] == 0],
        key=lambda e: priority.get(e, float("inf")),
    )

    while queue:
        current = queue.pop(0)
        result.append(current)
        for succ in successors[current]:
            indegree[succ] -= 1
            if indegree[succ] == 0:
                queue.append(succ)
        # keep queue sorted by priority after each insertion
        queue.sort(key=lambda e: priority.get(e, float("inf")))

    if len(result) != len(elements):
        raise ValueError("Cycle detected while merging orderings")

    return result

