def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    if object is None:
        raise TypeError("directlyProvidedBy() received None")
    try:
        # Prefer the attribute that specifically tracks directly provided interfaces
        return object.__directlyprovides__
    except AttributeError:
        try:
            # Fallback to __provides__ which may include indirectly provided interfaces
            return object.__provides__
        except AttributeError:
            raise TypeError(
                f"Object of type {type(object).__name__} does not provide interfaces"
            ) from None

