def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent."""
    # Validate input
    if not isinstance(classes, (list, tuple)):
        raise TypeError(f"Expected a list or tuple of classes, got {type(classes).__name__}")
    # Preserve first-seen order and deduplicate
    unique = []
    seen = set()
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"Expected class type, got {type(cls).__name__}")
        if cls not in seen:
            seen.add(cls)
            unique.append(cls)
    # Determine minimal list: exclude any class that is a superclass of another
    minimal = []
    for cls in unique:
        # Check if any other class in the list is a subclass of this class
        is_super = False
        for other in unique:
            if other is cls:
                continue
            try:
                if issubclass(other, cls):
                    is_super = True
                    break
            except TypeError:
                # If issubclass fails (unlikely since we verified types), ignore
                continue
        if not is_super:
            minimal.append(cls)
    return minimal

