def to_csv(self, separator=",", header=None):
    """Convert graph's points to CSV.

    Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Build list of CSV lines
    lines = []

    # Add header if supplied
    if header is not None:
        lines.append(str(header))

    # Determine the iterable of points
    # Try common attributes first, then fall back to iterator
    if hasattr(self, "points"):
        points_iterable = self.points
    elif hasattr(self, "data"):
        points_iterable = self.data
    else:
        try:
            points_iterable = list(self)
        except Exception:
            # Not iterable; nothing to write
            return "\n".join(lines)

    for point in points_iterable:
        # Interpret the point data
        # Default to treating the whole point as a value
        coords = None
        value = None
        if isinstance(point, tuple) and len(point) == 2:
            coords, value = point
        else:
            # Try to unpack first two elements if possible
            try:
                coords, value = point[0], point[1]
            except Exception:
                coord_parts = []
                val_parts = []

                # Handle multi‑value points (e.g., (x,y) -> 5)
                if isinstance(point, (list, tuple)):
                    for v in point:
                        val_parts.append(str(v))
                else:
                    val_parts.append(str(point))

                lines.append(separator.join(val_parts))
                continue

        # Build string for coordinates
        coord_parts = []
        if coords is not None:
            if isinstance(coords, (list, tuple)):
                for c in coords:
                    coord_parts.append(str(c))
            else:
                coord_parts.append(str(coords))

        # Build string for value parts
        val_parts = []
        if isinstance(value, (list, tuple)):
            for v in value:
                val_parts.append(str(v))
        else:
            val_parts.append(str(value))

        # Combine coordinate and value parts
        line_parts = coord_parts + val_parts
        lines.append(separator.join(line_parts))

    return "\n".join(lines)

