def _update_context(self, context):
        """Update *context* with the properties of this graph.

        *context.error* is appended with indices of errors.
        Example subcontext for a graph with fields "E,t,error_E_low":
        {"error": {"x_low": {"index": 2}}}.
        Note that error names are called "x", "y" and "z"
        (this corresponds to first three coordinates,
        if they are present), which allows to simplify plotting.
        Existing values are not removed
        from *context.value* and its subcontexts.

        Called on "destruction" of the graph (for example,
        in :class:`.ToCSV`). By destruction we mean conversion
        to another structure (like text) in the flow.
        The graph object is not really destroyed in this process.
        """
        # Ensure context.error exists
        if not hasattr(context, "error") or context.error is None:
            context.error = {}
        if not isinstance(context.error, dict):
            raise TypeError("context.error must be a dictionary")

        # Try to get the ordered list of field names that represent the graph
        field_order = None
        if hasattr(self, "field_names"):
            field_order = self.field_names
        elif hasattr(self, "_field_names"):
            field_order = getattr(self, "_field_names")
        elif hasattr(self, "fields"):
            # Some Graph implementations use a list of field objects/tuples
            fld = self.fields
            if isinstance(fld, list):
                field_order = [f if isinstance(f, str) else f.name if hasattr(f, "name") else "" for f in fld]
        # fallback: use sorted attribute names that don't start with underscore
        if not field_order:
            field_order = sorted([name for name in dir(self) if not name.startswith("_")])

        # Determine mapping for coordinate names (first three)
        coord_names = ["x", "y", "z"]
        for name in field_order:
            if not isinstance(name, str):
                continue
            if name.startswith("error_"):
                # Get index of this error field in the overall ordered list
                try:
                    idx = field_order.index(name)
                except ValueError:
                    # Jitter: maybe name not in list due to nested objects
                    continue
                # Determine base name after 'error_'
                base = name.split("error_")[-1]
                # Append '_low' or '_high' or other suffix if present
                # Build key like 'x_low' or 'y_high', etc.
                # Try to separate coordinate part from suffix
                # e.g., 'E_low' -> coordinate part 'E', suffix '_low'
                # We'll split by underscore, taking last part as suffix
                parts = base.split("_")
                if len(parts) >= 2:
                    # Assume last part is suffix
                    suffix = parts[-1]
                    # The preceding part(s) may represent coordinate name
                    coord_part = "_".join(parts[:-1])
                else:
                    suffix = ""
                    coord_part = parts[0]
                # Prefer mapping from stored coordinates if known; otherwise use coord_names
                coord_key = None
                # Check if coord_part appears in field_order preceding this error field
                # find index of coord_part in field_order
                for cand_idx, cand_name in enumerate(field_order[:idx]):
                    if cand_name == coord_part:
                        coord_idx = cand_idx
                        if coord_idx < 3:
                            coord_key = coord_names[coord_idx]
                        else:
                            coord_key = cand_name
                        break
                # If not found, try to map from field names that look like coordinate names
                if not coord_key:
                    # default to first three fields
                    for i, fld in enumerate(field_order[:idx]):
                        if i < 3:
                            coord_key = coord_names[i]
                            break
                if not coord_key:
                    coord_key = "coord"

                key = f"{coord_key}_{suffix}" if suffix else coord_key
                # Now insert into context.error
                if key not in context.error:
                    context.error[key] = {"index": idx}
                else:
                    # If already present, append index to list
                    existing = context.error[key]
                    if isinstance(existing, dict) and "index" in existing:
                        # convert to list
                        context.error[key] = {"index": [idx]}
                    elif isinstance(existing, dict) and isinstance(existing.get("index"), list):
                        existing["index"].append(idx)
                    # else leave as is (unlikely)
        # No return needed; method updates context in place.

def _update_context(self, context):
        """Update *context* with the properties of this graph.

        *context.error* is appended with indices of errors.
        Example subcontext for a graph with fields "E,t,error_E_low":
        {"error": {"x_low": {"index": 2}}}.
        Note that error names are called "x", "y" and "z"
        (this corresponds to first three coordinates,
        if they are present), which allows to simplify plotting.
        Existing values are not removed
        from *context.value* and its subcontexts.
        """
        # Ensure the context has an error dictionary
        try:
            error_dict = context.error
        except AttributeError:
            error_dict = {}
            context.error = error_dict

        # Determine the index to store, defaulting to the graph's own index if available
        base_index = getattr(self, "index", None)

        # Mapping from original coordinate letter to simplified name
        coord_map = {"E": "x", "t": "y", "z": "z"}

        for attr_name in dir(self):
            # Look for attributes that start with 'error_'
            if not attr_name.startswith("error_"):
                continue

            # Extract the suffix after 'error_'
            suffix = attr_name[len("error_") :]

            # Determine the simplified error name ('x_low', etc.)
            if suffix and suffix[0] in coord_map:
                new_name = coord_map[suffix[0]] + suffix[1 :]
            else:
                new_name = suffix

            # Attempt to find an explicit index for this error
            # Prefer a dedicated *_index attribute if it exists
            index = getattr(self, f"{attr_name}_index", None)

            # Fallback to the graph's own index if no error‑specific index is provided
            if index is None:
                index = base_index

            # If we have a usable index, record it in the context
            if index is not None:
                try:
                    # Ensure the nested dict for this error exists
                    if new_name not in error_dict:
                        error_dict[new_name] = {}
                    error_dict[new_name]["index"] = index
                except Exception:
                    # Silently ignore any context writing errors to avoid breaking the caller
                    continue

        # No modification to context.value is performed, as required.

