def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Validate input lengths
    if not isinstance(bins, (list, tuple)):
        raise TypeError(f"'bins' must be a list or tuple, got {type(bins).__name__}")
    if not isinstance(edges, (list, tuple)):
        raise TypeError(f"'edges' must be a list or tuple, got {type(edges).__name__}")

    if len(edges) != len(bins) + 1:
        raise ValueError("Length of edges must be one greater than length of bins.")

    # Verify numeric types and compute integral
    total = 0.0
    for i, (b, e0, e1) in enumerate(zip(bins, edges[:-1], edges[1:])):
        try:
            bin_val = float(b)
            width = float(e1 - e0)
        except Exception as exc:
            raise TypeError(f"Non-numeric value encountered in bins or edges at index {i}: {exc}") from exc

        if width < 0:
            raise ValueError(f"Edges are not in ascending order at positions {i} and {i+1} (edge values: {e0}, {e1}).")

        total += bin_val * width

    return total

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic validation
    if edges is None or bins is None:
        raise ValueError("Both bins and edges must be provided.")

    try:
        bins_list = list(bins)
    except Exception as exc:
        raise ValueError("bins must be an iterable of numeric values.") from exc

    try:
        edges_list = list(edges)
    except Exception as exc:
        raise ValueError("edges must be an iterable of numeric values.") from exc

    if len(edges_list) != len(bins_list) + 1:
        raise ValueError(
            f"edges length ({len(edges_list)}) must be one greater than bins length ({len(bins_list)})."
        )

    # Compute widths between successive edges
    widths = []
    for i in range(len(bins_list)):
        try:
            width = float(edges_list[i + 1]) - float(edges_list[i])
        except Exception as exc:
            raise ValueError(
                f"Could not compute width between edges[{i}] and edges[{i+1}]."
            ) from exc
        widths.append(width)

    try:
        integral_value = float(sum(b * w for b, w in zip(bins_list, widths)))
    except Exception as exc:
        raise ValueError("Error while computing the integral; ensure bins and widths are numeric.") from exc

    return integral_value

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Validate input types
    try:
        bins = list(bins)
        edges = list(edges)
    except TypeError:
        raise TypeError("bins and edges must be iterable sequences")

    # Basic length checks
    if not edges or len(edges) < 2:
        raise ValueError("edges must contain at least two values to define bin widths")
    if len(bins) != len(edges) - 1:
        raise ValueError("Number of bins must be one less than number of edges")

    # Validate numeric content and monotonicity of edges
    for i, e in enumerate(edges):
        if not isinstance(e, (int, float)):
            raise TypeError(f"edge at index {i} is not numeric: {e!r}")
        if i > 0 and edges[i-1] > e:
            raise ValueError(f"edges must be in non-decreasing order; edge[{i-1}]={edges[i-1]} > edge[{i}]={e}")

    total = 0.0
    for idx, (b, left, right) in enumerate(zip(bins, edges[:-1], edges[1:])):
        if not isinstance(b, (int, float)):
            raise TypeError(f"bin at index {idx} is not numeric: {b!r}")
        width = right - left
        total += b * width

    return total

