def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if seq is None:
        return False
    # Treat a Source as a sequence that should not be considered
    try:
        if isinstance(seq, Source):
            return False
    except NameError:
        # Source not defined, ignore
        pass
    # Directly a FillRequest element
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        pass

    # Iterate over the sequence if possible
    try:
        for element in seq:
            # Guard against string/bytes iteration
            if isinstance(element, (str, bytes)):
                continue
            if isinstance(element, FillRequest):
                return True
    except TypeError:
        # seq is not iterable
        pass

    return False

