def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    # Basic regexes for demonstration purposes. In real code these would be defined
    # elsewhere and imported into the module.
    LABEL_KEY_RE = re.compile(r'^[A-Za-z0-9_\-]+$')
    LABEL_VALUE_RE = re.compile(r'^[A-Za-z0-9_\- ]+$')

    errors = []

    if not isinstance(labels, dict):
        raise ValidationError({"labels": "labels must be a dict"})

    for key, value in labels.items():
        # --- Validate key ---
        if not isinstance(key, (str, bytes)):
            errors.append(
                {str(key): "expected string or bytes-like object"}
            )
        else:
            key_str = key if isinstance(key, str) else key.decode("utf-8", errors="ignore")
            if not LABEL_KEY_RE.fullmatch(key_str):
                errors.append(
                    {str(key): f"Label key {key!r} does not match the regex {LABEL_KEY_RE.pattern}"}
                )

        # --- Validate value ---
        # If value is a sequence (list/tuple), treat whole value as invalid.
        if isinstance(value, (list, tuple)):
            errors.append(
                {str(value): "expected string or bytes-like object"}
            )
        elif not isinstance(value, (str, bytes)):
            errors.append(
                {str(value): "expected string or bytes-like object"}
            )
        else:
            value_str = value if isinstance(value, str) else value.decode("utf-8", errors="ignore")
            if not LABEL_VALUE_RE.fullmatch(value_str):
                errors.append(
                    {str(value): f"Label value {value!r} does not match the regex {LABEL_VALUE_RE.pattern}"}
                )

    if errors:
        raise ValidationError(errors)

