def validate_value(value):
    """Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    import re
    # Ensure we have a string to validate
    if not isinstance(value, str):
        raise ValidationError(
            f"Expected a string for validation, got {type(value).__name__}"
        )

    # Retrieve the expected regular expression.  It must be defined
    # in the module's global namespace under the name VALID_REGEX.
    # Either a raw pattern string or a pre‑compiled `re.Pattern` can be used.
    pattern = globals().get("VALID_REGEX")
    if pattern is None:
        raise ValidationError(
            "No regular expression defined for value validation (missing VALID_REGEX)."
        )

    # If a raw pattern string is provided, compile it for matching.
    if isinstance(pattern, str):
        try:
            compiled = re.compile(pattern)
        except re.error as exc:
            raise ValidationError(f"Invalid regular expression: {exc}") from exc
    elif isinstance(pattern, re.Pattern):
        compiled = pattern
    else:
        raise ValidationError(
            f"VALID_REGEX must be a string or re.Pattern, got {type(pattern).__name__}"
        )

    # Perform the full match; raise if the value does not conform.
    if not compiled.fullmatch(value):
        raise ValidationError(
            f"Value '{value}' does not match the required pattern '{compiled.pattern}'."
        )
    # If we reach here, validation succeeded. Return None or True (spec does not require return).

