        )
        if not has_version:
            return False

        # Ensure each version directory contains its own ocfl.json
        for ver_dir in versions_dir.iterdir():
            if not ver_dir.is_dir():
                continue
            if not (ver_dir / "ocfl.json").is_file():
                return False

        return True
    except Exception:
        # In case of any unexpected errors, treat the object as invalid
        return False

