def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Normalise the used digests to a set
    try:
        used = set(digests_used)
    except TypeError:
        used = {digests_used}

    present_digests = set()
    missing_used = set()

    for entry in manifest_files:
        # Try to extract the digest from a variety of possible entry types
        digest = None
        if isinstance(entry, dict):
            digest = entry.get('digest') or entry.get('hash')
        else:
            # Any other iterable that isn't a string (e.g. tuple, list, NamedTuple)
            if hasattr(entry, '__iter__') and not isinstance(entry, (str, bytes)):
                try:
                    digest = list(entry)[0]
                except Exception:
                    pass

        if digest is None:
            continue

        present_digests.add(digest)
        if digest not in used:
            missing_used.add(digest)

    if missing_used:
        raise ValueError(
            f"The following digests from the manifest are not used: "
            f"{', '.join(sorted(missing_used))}"
        )

    # Check for used digests that aren't in the manifest
    unused = used - present_digests
    if unused:
        raise ValueError(
            f"The following digests are used but not present in the manifest: "
            f"{', '.join(sorted(unused))}"
        )

