def select_filenames_by_prefix(prefix, files):
    """
    Get files which belongs to a document package.

    Retorna os arquivos da lista `files` cujos nomes iniciam com `prefix`

    Parameters
    ----------
    prefix : str
        Filename prefix
    files : str list
        Files paths
    Returns
    -------
    list
        files paths which basename files matches to prefix
    """
    # Helper to extract basename without importing os
    def _basename(path):
        try:
            if not isinstance(path, str):
                return ''
            # Consider both forward slash and backslash as separators
            for sep in ('/', '\\'):
                idx = path.rfind(sep)
                if idx != -1:
                    path = path[idx + 1 :]
            return path
        except Exception:
            return ''

    # Validate inputs
    if not isinstance(prefix, str):
        raise TypeError(f"prefix must be a string, got {type(prefix).__name__}")
    if not isinstance(files, (list, tuple)):
        raise TypeError(f"files must be a list or tuple of strings, got {type(files).__name__}")

    result = []
    for file_path in files:
        # Skip non-string entries silently
        if not isinstance(file_path, str):
            continue
        try:
            base = _basename(file_path)
            if base.startswith(prefix):
                result.append(file_path)
        except Exception:
            # If any unexpected error occurs with this file, skip it
            continue
    return result

