def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    if not isinstance(folder, str):
        raise TypeError("folder must be a string path")
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Folder does not exist: {folder}")

    result = {}
    for root, _, files in os.walk(folder):
        for fname in files:
            base, ext = os.path.splitext(fname)
            full_path = os.path.join(root, fname)
            if base not in result:
                result[base] = {}
            result[base][ext.lower()] = full_path
    return result

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    if not isinstance(folder, str):
        raise TypeError(f"folder must be a str, got {type(folder).__name__}")

    if not os.path.isdir(folder):
        raise FileNotFoundError(f"The folder '{folder}' does not exist or is not a directory.")

    data = {}

    try:
        for entry in os.listdir(folder):
            full_path = os.path.join(folder, entry)
            if not os.path.isfile(full_path):
                continue

            base_name, _ = os.path.splitext(entry)
            data.setdefault(base_name, []).append(full_path)

    except PermissionError as exc:
        raise PermissionError(f"Permission denied while accessing '{folder}': {exc}") from exc
    except OSError as exc:
        raise OSError(f"Error while accessing folder '{folder}': {exc}") from exc

    # Sorting the lists for deterministic results
    for key in data:
        data[key].sort()

    return data

