def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Base indentation string
    indent_str = ' ' * indent

    # Start with the class name (or tag if present)
    if hasattr(self, 'tag'):
        try:
            name = getattr(self, 'tag')
        except Exception:
            name = self.__class__.__name__
    else:
        name = self.__class__.__name__

    # Include an id attribute if one exists
    if hasattr(self, 'id') and self.id:
        name += f' (id={self.id})'

    # Include attributes if any
    attrs = []
    if hasattr(self, 'attrib') and isinstance(self.attrib, dict):
        for k, v in self.attrib.items():
            attrs.append(f'{k}="{v}"')
    else:
        # Guess dictionary-like attributes through introspection
        try:
            attrs_dict = getattr(self, 'attributes')
            if isinstance(attrs_dict, dict):
                for k, v in attrs_dict.items():
                    attrs.append(f'{k}="{v}"')
        except Exception:
            pass

    if attrs:
        name += f' [{", ".join(attrs)}]'

    result = f'{indent_str}{name}'

    # Add debug information if requested
    if debug:
        try:
            debug_info = repr(self)
            result += f'  [debug: {debug_info}]'
        except Exception:
            pass

    # Recursively pretty-print child elements
    # We assume that the element is iterable over its children
    try:
        for child in self:
            child_str = child.pretty(indent=indent + 2, debug=debug)
            result += f'\n{child_str}'
    except TypeError:
        # Object is not iterable; no children
        pass
    except Exception:
        # In case accessing children raises an unexpected exception,
        # we simply ignore it and return the current representation.
        pass

    return result

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self.

    If ``debug`` is ``True`` the output contains the class name, the
    instance's ``id`` attribute (if present) and a repr of each attribute.
    Otherwise the output merely shows the object as a placeholder
    followed by pretty representations of its children (if the object
    is iterable). the ``indent`` parameter controls the amount of
    indentation for nested items and is expressed in spaces.
    """
    # Helper to format indented lines
    def _indent(text, level):
        return ' ' * level + text

    # Build lines list
    lines = []

    # Special case: if object already has a dedicated pretty method that
    # expects a different signature, fall back to its output.
    if debug:
        # Show class name and id if available
        cls_name = self.__class__.__name__
        obj_id = getattr(self, 'id', None)
        header = f"<{cls_name} id={obj_id}>"
        lines.append(_indent(header, indent))

        # Go through attributes (excluding private ones)
        for attr, val in sorted(self.__dict__.items()):
            if attr.startswith('_'):
                continue
            # For collections, pretty print each element
            if isinstance(val, (list, tuple)):
                lines.append(_indent(f"{attr}=[", indent + 2))
                for item in val:
                    if hasattr(item, 'pretty') and callable(item.pretty):
                        lines.append(item.pretty(indent + 4, debug))
                    else:
                        lines.append(_indent(repr(item), indent + 4))
                lines.append(_indent("]", indent + 2))
            elif hasattr(val, 'pretty') and callable(val.pretty):
                lines.append(_indent(f"{attr}=", indent + 2))
                lines.append(val.pretty(indent + 4, debug))
            else:
                lines.append(_indent(f"{attr}={repr(val)}", indent + 2))

        lines.append(_indent("</{0}>".format(cls_name), indent))
    else:
        # Plain representation: show type and iterate over children
        lines.append(_indent(f"<{self.__class__.__name__}>", indent))
        try:
            children = list(self)
        except TypeError:
            children = []

        for child in children:
            if hasattr(child, 'pretty') and callable(child.pretty):
                lines.append(child.pretty(indent + 2, debug))
            else:
                lines.append(_indent(repr(child), indent + 2))
        lines.append(_indent(f"</{self.__class__.__name__}>", indent))

    return '\n'.join(lines)

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    indentation = ' ' * indent
    result_lines = []

    # Header with class name and optional debugging info
    if debug:
        header = f"{indentation}{self.__class__.__name__} (id={hex(id(self))})("
    else:
        header = f"{indentation}{self.__class__.__name__}("
    result_lines.append(header)

    # Gather attributes (supports objects with __dict__ or __slots__)
    attrs = {}
    try:
        if hasattr(self, '__dict__'):
            attrs = dict(self.__dict__)
        else:
            slots = getattr(self, '__slots__', [])
            for slot_name in slots:
                try:
                    attrs[slot_name] = getattr(self, slot_name)
                except AttributeError:
                    continue
