        pass  # If any error retrieving attrs, ignore

    # Add attribute lines
    for key in sorted(attrs):
        val = attrs[key]
        # Recursively pretty-print if possible
        if hasattr(val, 'pretty') and callable(val.pretty) and val is not self:
            try:
                val_str = val.pretty(indent + 4, debug)
            except Exception:
                try:
                    val_str = repr(val)
                except Exception:
                    val_str = str(val)
        else:
            try:
                val_str = repr(val)
            except Exception:
                val_str = str(val)
        result_lines.append(f"{indentation}    {key}={val_str}")

    # Add child elements if the object is iterable
    try:
        for child in self:
            if child is self:
                continue  # avoid self-reference loop
            if hasattr(child, 'pretty') and callable(child.pretty):
                try:
                    child_str = child.pretty(indent + 4, debug)
                except Exception:
                    child_str = f"{' '*(indent+4)}{repr(child)}"
            else:
                child_str = f"{' '*(indent+4)}{repr(child)}"
            result_lines.append(child_str)
    except Exception:
        pass  # If the object is not iterable, ignore

    # Close the representation
    result_lines.append(f"{indentation})")
    return '\n'.join(result_lines)

