def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess, shlex, os
    # Validate inputs
    if commands is None:
        raise ValueError("`commands` must not be None")
    if isinstance(commands, str):
        cmd_parts = shlex.split(commands)
    elif isinstance(commands, (list, tuple)):
        cmd_parts = list(commands)
    else:
        raise TypeError("`commands` must be a str, list, or tuple")
    if args is None:
        args_parts = []
    elif isinstance(args, str):
        args_parts = shlex.split(args)
    elif isinstance(args, (list, tuple)):
        args_parts = list(args)
    else:
        raise TypeError("`args` must be a str, list, or tuple")
    full_cmd = cmd_parts + args_parts
    if verbose:
        msg = f"Running command: {' '.join(full_cmd)}"
        if cwd:
            msg += f" (cwd={cwd})"
        print(msg)
    # Prepare environment
    command_env = os.environ.copy()
    if env:
        if not isinstance(env, dict):
            raise TypeError("`env` must be a dict or None")
        command_env.update(env)
    try:
        stderr_target = subprocess.DEVNULL if hide_stderr else subprocess.PIPE
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=command_env,
            stdout=subprocess.PIPE,
            stderr=stderr_target,
            text=True
        )
        stdout = result.stdout
        stderr = result.stderr if not hide_stderr else ''
        if result.returncode != 0:
            raise subprocess.CalledProcessError(
                result.returncode,
                full_cmd,
                output=stdout,
                stderr=stderr
            )
        return result.returncode, stdout, stderr
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {full_cmd[0]}") from e
    except subprocess.SubprocessError as e:
        raise RuntimeError(f"Error running command: {' '.join(full_cmd)}") from e

