def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os
    import shlex

    if commands is None:
        raise ValueError("commands must not be None")

    # Normalize commands to a list of arguments
    if isinstance(commands, str):
        base_cmd = shlex.split(commands)
    else:
        try:
            base_cmd = list(commands)
        except TypeError:
            raise TypeError("commands must be a string or an iterable of strings")

    # Normalize args to a list
    if args is None:
        args_list = []
    else:
        if isinstance(args, str):
            # Allow a single string of arguments
            args_list = shlex.split(args)
        else:
            try:
                args_list = list(args)
            except TypeError:
                raise TypeError("args must be a string or an iterable of strings")

    full_cmd = base_cmd + args_list

    # Prepare the environment
    if env is not None:
        if not isinstance(env, dict):
            raise TypeError("env must be a mapping or None")
        env_combined = os.environ.copy()
        env_combined.update(env)
    else:
        env_combined = None  # subprocess will use os.environ

    # Setup stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else None

    if verbose:
        cmd_str = subprocess.list2cmdline(full_cmd)
        wd = cwd or os.getcwd()
        print(f"Running command: {cmd_str}")
        print(f"In working directory: {wd}")

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env_combined,
            stdout=subprocess.PIPE,
            stderr=stderr,
            text=True,
            check=True
        )
        return result
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command '{' '.join(full_cmd)}' failed with exit code {e.returncode}")
        # Re-raise with original exception to preserve stack trace
        raise
    except FileNotFoundError as e:
        if verbose:
            print(f"Command not found: {full_cmd[0]}")
        raise
    except Exception as e:
        if verbose:
            print(f"Unexpected error running command: {e}")
        raise

