def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    stack = [self]
    while stack:
        node = stack.pop()
        if node is None:
            continue
        num_objects += 1
        is_good = True
        # Validate object if requested
        if validate_objects and hasattr(node, "validate") \
                and callable(getattr(node, "validate")):
            try:
                node.validate()
            except Exception as exc:
                is_good = False
                if show_warnings:
                    try:
                        name = getattr(node, "id", repr(node))
                    except Exception:
                        name = repr(node)
                    print(f"Warning: validation failed for {name}: {exc}")
        # Check digests if requested
        if check_digests and hasattr(node, "digest") \
                and hasattr(node, "compute_digest") \
                and callable(getattr(node, "compute_digest")):
            try:
                computed = node.compute_digest()
                if computed != node.digest:
                    is_good = False
                    if show_warnings:
                        try:
                            name = getattr(node, "id", repr(node))
                        except Exception:
                            name = repr(node)
                        print(f"Warning: digest mismatch for {name}")
            except Exception as exc:
                is_good = False
                if show_warnings:
                    try:
                        name = getattr(node, "id", repr(node))
                    except Exception:
                        name = repr(node)
                    print(f"Warning: digest check failed for {name}: {exc}")
        if is_good:
            good_objects += 1
        # Add children to stack if node is iterable
        try:
            for child in node:
                stack.append(child)
        except TypeError:
            # Not iterable, nothing to do
            continue
    return num_objects, good_objects

