            describing any digest differences found.  If the root has no record for a file,
            ``root_digest`` will be ``None``.  Files that appear in a version inventory but
            are not present in any later version are not reported.

        Raises
        ------
        TypeError
            If ``version_dirs`` is not a list or tuple.
        FileNotFoundError
            If a specified version directory or the root inventory cannot be found.
        """
        # Basic validation of input
        if not isinstance(version_dirs, (list, tuple)):
            raise TypeError("version_dirs must be a list or tuple of directory names")

        import os
        import json

        # Helper to load inventory file from a given directory
        def _load_inventory(dir_path):
            for fname in ("inventory.json", "inventory.yaml", "inventory.yml"):
                full = os.path.join(dir_path, fname)
                if os.path.isfile(full):
                    try:
                        with open(full, "r", encoding="utf-8") as f:
                            if fname.endswith(".json"):
                                return json.load(f)
                            else:
                                # simplest YAML handling without external libs
                                try:
                                    import yaml
                                except Exception:
                                    return None
                                return yaml.safe_load(f)
                    except Exception:
                        # Skip unreadable inventory
                        return None
            return None

        # Resolve root inventory path
        if not hasattr(self, "root_dir"):
            raise AttributeError("Instance must have a 'root_dir' attribute pointing to the project root")

        root_inventory_path = os.path.join(self.root_dir, "inventory.json")
        if not os.path.isfile(root_inventory_path):
            raise FileNotFoundError(f"Root inventory not found at {root_inventory_path}")

        try:
            with open(root_inventory_path, "r", encoding="utf-8") as f:
                root_inventory = json.load(f)
        except Exception as exc:
            raise FileNotFoundError(f"Could not read root inventory: {exc}")

        # Expect root_inventory to contain a 'files' mapping of path -> {'digest': <hash>}
        root_files = {}
        try:
            root_files = root_inventory.get("files", {})
        except AttributeError:
            pass

        inconsistent = {}

        for ver_name in version_dirs:
            ver_path = os.path.join(self.root_dir, ver_name)
            if not os.path.isdir(ver_path):
                raise FileNotFoundError(f"Version directory '{ver_name}' does not exist at {ver_path}")

            ver_inventory = _load_inventory(ver_path)
            if ver_inventory is None:
                # No inventory to validate for this version; skip gracefully
                continue

