def deep_merge_nodes(nodes):
    '''
    Deep merge nodes with duplicate keys as described in the docstring.
    '''
    # Helper to determine if a node is a mapping node.
    def _is_mapping(n):
        return hasattr(n, 'tag') and n.tag == 'tag:yaml.org,2002:map'

    # Recursive merge of two mapping nodes
    def _merge_mapping(node1, node2):
        try:
            # Build dict from node1 preserving order
            order = []
            mapping = {}
            for k_node, v_node in node1.value:
                key = k_node.value
                mapping[key] = (k_node, v_node)
                order.append(key)
            # Merge node2
            for k_node, v_node in node2.value:
                key = k_node.value
                if key in mapping:
                    _, existing_val = mapping[key]
                    if _is_mapping(existing_val) and _is_mapping(v_node):
                        merged_val = _merge_mapping(existing_val, v_node)
                        mapping[key] = (mapping[key][0], merged_val)
                    else:
                        # last wins
                        mapping[key] = (mapping[key][0], v_node)
                else:
                    mapping[key] = (k_node, v_node)
                    order.append(key)
            # Reconstruct new value list
            new_value = [(mapping[k][0], mapping[k][1]) for k in order]
            # Create new MappingNode with same tag and flow_style
            flow = getattr(node1, 'flow_style', None)
            return type(node1)(node1.tag, new_value, flow)
        except Exception as exc:
            raise ValueError(f'Error merging mapping nodes: {exc}') from exc

    # Main algorithm
    if not isinstance(nodes, (list, tuple)):
        raise TypeError('nodes must be a list or tuple')
    result_map = {}
    order_keys = []
    for item in nodes:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError(f'Each item must be a tuple of 2 elements, got {item}')
        key_node, val_node = item
        if not hasattr(key_node, 'value'):
            raise ValueError(f'Expected key node with .value, got {key_node}')
        key = key_node.value
        if key in result_map:
            existing_key_node, existing_val_node = result_map[key]
            if _is_mapping(existing_val_node) and _is_mapping(val_node):
                merged_val = _merge_mapping(existing_val_node, val_node)
                result_map[key] = (existing_key_node, merged_val)
            else:
                result_map[key] = (existing_key_node, val_node)
        else:
            result_map[key] = (key_node, val_node)
            order_keys.append(key)
    # Build final result list
    result = [(result_map[k][0], result_map[k][1]) for k in order_keys]
