def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    import argparse
    parser = argparse.ArgumentParser()
    # Define subparsers container so that any subcommand definition that
    # might be added later can be attached. Even if no subcommands are added,
    # this allows the parser to recognize a subparser argument if it is passed.
    parser.add_subparsers(dest='subparser', required=False)
    try:
        namespace, unknown = parser.parse_known_args(unparsed_arguments)
    except Exception as exc:
        # In case of a parsing error, raise a ValueError with a clear message.
        raise ValueError(f"Argument parsing failed: {exc}") from exc

    # Build the mapping.  If a subparser name was detected, use it as the
    # key; otherwise fall back to "global".
    key = getattr(namespace, 'subparser', None)
    if key:
        return {key: namespace}
    else:
        return {'global': namespace}

