def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not isinstance(size, str):
        raise ValueError("size must be a string")
    s = size.strip()
    if not s:
        raise ValueError("size string is empty")
    # Extract numeric part
    num_str = ""
    idx = 0
    while idx < len(s) and (s[idx].isdigit() or s[idx] == "."):
        num_str += s[idx]
        idx += 1
    if not num_str:
        raise ValueError(f"No numeric value found in size '{size}'")
    try:
        number = float(num_str)
    except ValueError:
        raise ValueError(f"Invalid numeric value '{num_str}' in size '{size}'")
    # Extract unit part
    unit = s[idx:].strip().upper()
    # Determine multiplier
    if unit in ("", "B"):
        mult = 1
    elif unit in ("K", "KB", "KIB"):
        mult = 1000
    elif unit in ("M", "MB", "MIB"):
        mult = 1000**2
    elif unit in ("G", "GB", "GIB"):
        mult = 1000**3
    elif unit in ("T", "TB", "TIB"):
        mult = 1000**4
    elif unit in ("P", "PB", "PIB"):
        mult = 1000**5
    else:
        raise ValueError(f"Unknown unit '{unit}' in size '{size}'")
    # Compute and return integer byte size
    return int(round(number * mult))

