def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    try:
        # Direct None is considered a None value
        if val is None:
            return True

        # Only string values can represent a textual None
        if isinstance(val, str):
            cleaned = val.strip().lower()
            # Common textual representations of None
            none_tokens = {"", "none", "null", "na", "n/a", "nan", "nil"}
            return cleaned in none_tokens

        # Non-string types are not textual None representations
        return False
    except Exception:
        # In case of unexpected errors, be conservative and return False
        return False

