    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Base must be at least 2 for a meaningful representation
    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two distinct characters to represent a base.")

    # Build a quick lookup table for digit values
    mapping = {char: idx for idx, char in enumerate(alphabet)}

