import sys, shlex, re

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1

    if platform == 1:
        # POSIX behaviour
        try:
            return shlex.split(s, posix=True)
        except Exception as exc:
            raise ValueError(f"POSIX split failed for input {s!r}") from exc

    elif platform == 0:
        # Windows CMD-style splitting
        token_pattern = re.compile(
            r'''
            (?:\s+)                                  # Skip leading whitespace
            (?:
                "([^"\\]*(?:\\.[^"\\]*)*)"           # quoted part
                |([^\s]+)                            # unquoted part
            )
            ''',
            re.VERBOSE
        )

        tokens = []
        for match in token_pattern.finditer(s):
            quoted, unquoted = match.group(1), match.group(2)
            if quoted is not None:
                # Replace escaped quotes and backslashes
                token = quoted.replace(r'\"', '"').replace(r'\\', '\\')
                # Interpret other escape sequences
                try:
                    token = bytes(token, "utf-8").decode("unicode_escape")
                except Exception:
                    pass  # leave as is if decoding fails
            else:
                token = unquoted
            tokens.append(token)
        return tokens

    else:
        raise ValueError(f"Unsupported platform value: {platform}")

