def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import subprocess
    import tempfile
    from pathlib import Path

    # Resolve archive path
    archive = Path(archive_path).expanduser().resolve()
    if not archive.is_file():
        raise FileNotFoundError(f"Archive file does not exist: {archive}")

    # Resolve and create temporary directory if necessary
    tmp_dir = Path(tmp_path).expanduser().resolve()
    tmp_dir.mkdir(parents=True, exist_ok=True)

    # Create a uniquely named extraction directory
    if filename is None:
        # Use the base name of the archive without its extension
        base_name = Path(archive.stem).stem  # Handles .tar.gz, .tgz, etc.
        extraction_dir = tmp_dir / base_name
    else:
        extraction_dir = tmp_dir / filename
    extraction_dir.mkdir(parents=True, exist_ok=True)

    # Determine extraction command based on archive type
    archive_name = archive.name.lower()
    try:
        if archive_name.endswith(".zip"):
            cmd = ["unzip", "-q", str(archive), "-d", str(extraction_dir)]
        elif archive_name.endswith((".tar.gz", ".tgz", ".tar")):
            # Determine whether it's gzip or plain tar
            if archive_name.endswith(".tar.gz") or archive_name.endswith(".tgz"):
                cmd = ["tar", "-xzf", str(archive), "-C", str(extraction_dir)]
            else:
                cmd = ["tar", "-xf", str(archive), "-C", str(extraction_dir)]
        elif archive_name.endswith((".tar.bz2", ".tbz2")):
            cmd = ["tar", "-xjf", str(archive), "-C", str(extraction_dir)]
        else:
            raise ValueError(f"Unsupported archive format: {archive}")
        subprocess.check_call(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
    except subprocess.CalledProcessError as exc:
        # Clean up potentially partially extracted files
        try:
            if extraction_dir.is_dir():
                for child in extraction_dir.iterdir():
                    if child.is_file():
                        child.unlink()
                    else:
                        # Remove directories recursively
                        import shutil

                        shutil.rmtree(child, ignore_errors=True)
                extraction_dir.rmdir()
        except Exception:
            pass
        raise RuntimeError(f"Extraction failed for {archive}: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Error preparing repository from {archive}: {exc}") from exc

    # Return a file URL that can be used as a Git remote URL
    repo_url = f"file://{extraction_dir}"
    return repo_url

