            if extraction_dir.is_dir():
                for child in extraction_dir.iterdir():
                    if child.is_file():
                        child.unlink()
                    else:
                        # Remove directories recursively
                        import shutil

                        shutil.rmtree(child, ignore_errors=True)
                extraction_dir.rmdir()
        except Exception:
            pass
        raise RuntimeError(f"Extraction failed for {archive}: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Error preparing repository from {archive}: {exc}") from exc

    # Return a file URL that can be used as a Git remote URL
    repo_url = f"file://{extraction_dir}"
    return repo_url

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    from pathlib import Path
    import uuid

    archive = Path(archive_path)
    if not archive.exists():
        raise FileNotFoundError(f"Archive file not found: {archive_path}")

    tmp_dir = Path(tmp_path)
    try:
        tmp_dir.mkdir(parents=True, exist_ok=True)
    except Exception as exc:
        raise RuntimeError(f"Could not create temporary directory '{tmp_dir}': {exc}") from exc

    extraction_dir = tmp_dir / f"extracted_{uuid.uuid4().hex}"
    extraction_dir.mkdir()

    try:
        if archive.suffix.lower() == ".zip":
            subprocess.run(
                ["unzip", "-q", str(archive), "-d", str(extraction_dir)],
                check=True,
            )
        else:
            # tar handles .tar, .tar.gz, .tgz, .tar.bz2 etc.
            subprocess.run(
                ["tar", "-xf", str(archive), "-C", str(extraction_dir)],
                check=True,
            )
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"Failed to extract archive '{archive_path}': {exc}") from exc

    result_path = extraction_dir
    if filename:
        result_path = result_path / filename

    return f"file://{result_path}"

