def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    import datetime

    if frequency is None:
        return None
    freq_str = str(frequency).strip()
    if not freq_str:
        raise ValueError("Frequency string is empty")
    if freq_str.lower() == 'always':
        return None

    # split number and unit
    parts = freq_str.split(maxsplit=1)
    if len(parts) != 2:
        raise ValueError(f"Cannot parse frequency: '{frequency}' (expected '<number> <unit>')")
    number_str, unit_str = parts
    try:
        number = float(number_str)
    except ValueError:
        raise ValueError(f"Invalid number in frequency: '{number_str}'")

    unit = unit_str.lower()
    kwargs = {}
    if unit in ('day', 'days'):
        kwargs['days'] = number
    elif unit in ('week', 'weeks'):
        kwargs['weeks'] = number
    elif unit in ('hour', 'hours'):
        kwargs['hours'] = number
    elif unit in ('minute', 'minutes'):
        kwargs['minutes'] = number
    elif unit in ('second', 'seconds'):
        kwargs['seconds'] = number
    elif unit in ('month', 'months'):
        # approximate month as 30 days
        kwargs['days'] = number * 30
    elif unit in ('year', 'years'):
        # approximate year as 365 days
        kwargs['days'] = number * 365
    else:
        raise ValueError(f"Unrecognized time unit in frequency: '{unit_str}'")

    # If the value is an integer (e.g., 3.0), convert to int to avoid fractional
    for key, val in kwargs.items():
        if isinstance(val, float) and val.is_integer():
            kwargs[key] = int(val)

    return datetime.timedelta(**kwargs)

