    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # direct string comparisons for common loopback names
    common_loopbacks = {'localhost', '127.0.0.1', '::1'}
    if host in common_loopbacks:
        return True

    try:
        # Resolve host to all address info
        for res in socket.getaddrinfo(host, None):
