    Checks if the host is the localhost.

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Validate input
    if host is None:
        return False

    host_str = str(host).strip()
    if not host_str:
        return False

    # Common textual indicator
    if host_str.lower() == "localhost":
        return True

    try:
        # Resolve the host once to catch obvious errors
        resolved_ip = socket.gethostbyname(host_str)
    except Exception:
        # Could not resolve, not localhost
        return False

    # Check IPv4 loopback range (127.0.0.0/8)
    if resolved_ip.startswith("127.") or resolved_ip == "0.0.0.0":
        return True

    # For IPv6 addresses we need to use getaddrinfo
    try:
        info_list = socket.getaddrinfo(host_str, None, proto=socket.IPPROTO_TCP)
    except Exception:
        # Not resolvable, not localhost
        return False

    for info in info_list:
        family, _, _, _, sockaddr = info
        # sockaddr is (address, port) for IPv4 and IPv6 addresses
        address = sockaddr[0]
        if family == socket.AF_INET6:
            if address == "::1":
                return True
        elif family == socket.AF_INET:
            # IPv4 addresses already checked above, but double‑check
            if address.startswith("127.") or address == "0.0.0.0":
                return True

    return False

