    :return: True if the host is the localhost
    """
    if not isinstance(host, str):
        return False
    host = host.strip()
    if not host:
        return False
    # Quick hostname checks
    if host.lower() in ('localhost', 'localhost.localdomain'):
        return True
    # Check if the host string is a literal IP address
    try:
        socket.inet_aton(host)  # IPv4 literal
        if host == '127.0.0.1':
            return True
    except socket.error:
        pass
    try:
        # Some systems may not support inet_pton
        socket.inet_pton(socket.AF_INET6, host)  # IPv6 literal
        if host == '::1':
            return True
    except (OSError, AttributeError):
        pass
    # Resolve the hostname to IPs and check against loopback addresses
    try:
        for res in socket.getaddrinfo(host, None, socket.AF_UNSPEC, socket.SOCK_STREAM):
            family, _, _, _, sockaddr = res
            if family == socket.AF_INET:
                ipaddr = sockaddr[0]
                if ipaddr == '127.0.0.1':
                    return True
            elif family == socket.AF_INET6:
                ipaddr = sockaddr[0]
                if ipaddr == '::1':
                    return True
    except Exception:
        # If resolution fails, consider it not local
        return False
    return False

