def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    """
    # Validate input: must be an iterable of strings
    try:
        iter(find_paths)
    except Exception:
        raise TypeError('find_paths must be an iterable of strings or string-like objects')

    result = []
    for p in find_paths:
        # Skip falsy values, treat as empty strings rather than errors
        if p is None or p == '':
            continue

        # Ensure we are working with a string
        if not isinstance(p, str):
            try:
                p = str(p)
            except Exception:
                continue

        # Detect existing patterns: any wildcard or colon (e.g., scheme prefixes)
        if ':' in p or re.search(r'[*?[\]]', p):
            result.append(p)
        else:
            # Wrap fragment into a recursive glob pattern
            result.append('sh:**/*{}*/**'.format(p))

    return result

