def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    """
    # Normalize and expand user directory
    target_path = os.path.abspath(os.path.expanduser(config_filename))

    # If file exists and overwrite is not allowed, abort
    if os.path.exists(target_path) and not overwrite:
        raise FileExistsError(
            f"Configuration file '{target_path}' already exists and overwrite is False."
        )

    # Ensure the parent directory exists
    parent_dir = os.path.dirname(target_path)
    if parent_dir:
        try:
            os.makedirs(parent_dir, exist_ok=True)
        except OSError as exc:
            raise OSError(f"Failed to create directory '{parent_dir}': {exc}") from exc

    # Write the rendered configuration to the file
    try:
        with open(target_path, "w", encoding="utf-8") as fp:
            fp.write(rendered_config)
        # Set permissions to the desired mode
        try:
            os.chmod(target_path, mode)
        except OSError as exc:
            # Permissions change failed; log and continue
            raise OSError(f"Failed to set permissions on '{target_path}': {exc}") from exc
    except OSError as exc:
        raise OSError(f"Unable to write configuration file '{target_path}': {exc}") from exc
    return target_path

