def oneline(script, separator=" && "):
    """converts a script to one line command.
    This is useful to run a single ssh command and pass a one line script.

    :param script: a string or iterable of strings representing the script
    :return: a single‑line string with commands joined by ``separator``
    """
    if script is None:
        raise ValueError("script cannot be None")
    # Determine lines from string or iterable
    if isinstance(script, str):
        lines = script.splitlines()
    else:
        try:
            lines = list(script)
        except TypeError as exc:
            raise ValueError(f"script must be a string or iterable of strings: {exc}") from exc
    # Strip whitespace and ignore empty lines
    cleaned = [line.strip() for line in lines if line.strip()]
    # Join with the specified separator
    return separator.join(cleaned)

