    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Extract variable name and default value from the matcher.
    # Support both match objects and objects with a __dict__-like interface.
    try:
        # Prefer named groups if present
        if hasattr(matcher, 'groupdict'):
            groups = matcher.groupdict()
            var_name = groups.get('name')
            default = groups.get('default')
