def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate inputs
    if isinstance(commands, str):
        cmd = [commands]
    elif isinstance(commands, (list, tuple)):
        if not all(isinstance(c, str) for c in commands):
            raise TypeError("All elements of 'commands' must be strings")
        cmd = list(commands)
    else:
        raise TypeError("'commands' must be a string or a sequence of strings")

    if args is None:
        args = []
    elif not isinstance(args, (list, tuple)):
        raise TypeError("'args' must be a list or tuple of strings")
    elif not all(isinstance(a, str) for a in args):
        raise TypeError("All elements of 'args' must be strings")

    full_cmd = cmd + list(args)

    if verbose:
        print("Running command:", " ".join(full_cmd))

    subprocess_kwargs = {
        "cwd": cwd,
        "env": env,
        "text": True,
        "capture_output": True,
        "check": True,
    }

    if hide_stderr:
