def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    if roots is None:
        roots = set()
    else:
        # ensure we are working with a set
        if not isinstance(roots, set):
            try:
                roots = set(roots)
            except Exception as exc:
                raise TypeError("roots must be a set or convertible to set") from exc

    if graph is None:
        # nothing to process
        return roots

    subjects = set()
    objects = set()

    # walk all triples that use the given property
    try:
        for sub, _, obj in graph.triples((None, prop, None)):
            subjects.add(sub)
            objects.add(obj)
    except Exception:
        # If the graph doesn't support the triples method, try other iterators
        try:
            for triple in graph:
                sub, p, obj = triple
                if p == prop:
                    subjects.add(sub)
                    objects.add(obj)
        except Exception as exc:
            raise ValueError("Unable to iterate over the graph to find roots") from exc

    # Roots are nodes which appear as a parent (object) but never as a child (subject)
    roots.update(objects - subjects)

    return roots

