    """Dump to a py2-unicode or py3-string"""
    try:
        if dumper is None:
            # Default safe dumper
            s = yaml.safe_dump(obj, default_flow_style=False, allow_unicode=True)
        else:
            # If a class/prototype is supplied, instantiate it
            if isinstance(dumper, type):
                dumper = dumper()
