def make_array(shape, dtype=np.dtype("float32")):
    """Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate shape
    if not isinstance(shape, (tuple, list)):
        raise TypeError(f"shape must be a tuple or list of ints, got {type(shape).__name__}")
    # Ensure dtype is a numpy.dtype instance
    if not isinstance(dtype, np.dtype):
        try:
            dtype = np.dtype(dtype)
        except Exception as exc:
            raise TypeError(f"dtype must be convertible to a numpy dtype, got {dtype}") from exc
    # Create and return the array
    return np.empty(shape, dtype=dtype)

def make_array(shape, dtype=np.dtype("float32")):
    """Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    try:
        if not isinstance(shape, (tuple, list)):
            raise TypeError("shape must be a tuple or list of integers")
        if not all(isinstance(s, int) and s >= 0 for s in shape):
            raise ValueError("shape elements must be non-negative integers")
        return np.empty(shape, dtype=dtype)
    except Exception as exc:
        raise ValueError(f"Failed to create array with shape {shape} and dtype {dtype}: {exc}")

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple or iterable
        shape of the array to create
    dtype : numpy.dtype or convertible
        data-type of the array to create
    """
    # Validate and normalise shape
    try:
        shape_tuple = tuple(shape)
    except TypeError:
        raise TypeError(f"shape must be an iterable of integers, got {shape!r}")

    if len(shape_tuple) == 0:
        # Allow zero-dimensional arrays
        pass

    for dim in shape_tuple:
        if not isinstance(dim, int):
            raise TypeError(f"All dimensions in shape must be integers, got {type(dim).__name__}")
        if dim < 0:
            raise ValueError(f"All dimensions in shape must be non-negative, got {dim}")

    # Validate dtype
    try:
        dtype_obj = np.dtype(dtype)
    except Exception as exc:
        raise ValueError(f"Invalid dtype: {dtype}") from exc

    # Create the array (default to zeros)
    try:
        array = np.zeros(shape_tuple, dtype=dtype_obj)
    except Exception as exc:
        raise ValueError(f"Unable to create array with shape {shape_tuple} and dtype {dtype_obj}") from exc

    return array

