def gaussian(x):
    """Gaussian centered around 0.2 with a sigma of 0.1."""
    μ = 0.2
    σ = 0.1
    try:
        x_arr = np.asarray(x)
    except Exception as exc:
        raise ValueError("Input must be a number or array-like of numbers") from exc

    norm = 1 / (σ * np.sqrt(2 * np.pi))
    return norm * np.exp(-((x_arr - μ) ** 2) / (2 * σ ** 2))

