def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import logging
    import re

    configs = {}
    error_records = []

    # Attempt to import yaml if available
    try:
        import yaml  # type: ignore
    except ImportError:
        yaml = None

    log = logging.getLogger(__name__)

    def create_error_record(exc, fname):
        """Create a LogRecord for an exception."""
        return log.makeRecord(
            name=log.name,
            level=logging.ERROR,
            fn=fname,
            lno=0,
            msg=str(exc),
            args=(),
            exc_info=None,
            func=None,
            sinfo=None,
        )

    def resolve_env_vars(value):
        """Recursively resolve ${VAR} in strings."""
        if isinstance(value, str):
            patterns = re.findall(r'\${([^}]+)}', value)
            for var in patterns:
                env_val = os.getenv(var, '')
                value = value.replace(f'${{{var}}}', env_val)
            return value
        elif isinstance(value, dict):
            return {k: resolve_env_vars(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [resolve_env_vars(v) for v in value]
        else:
            return value

    def merge_override(base, override):
        """Merge override dict into base dict."""
        for key, val in override.items():
            if key in base and isinstance(base[key], dict) and isinstance(val, dict):
                merge_override(base[key], val)
            else:
                base[key] = val

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                data = f.read()
            # Determine parser
            if fname.lower().endswith(('.json', '.jsn')):
                parsed = json.loads(data)
            elif fname.lower().endswith(('.yaml', '.yml')):
                if yaml is None:
                    raise RuntimeError(f'PyYAML not installed, cannot parse {fname}')
                parsed = yaml.safe_load(data)
            else:
                # Try JSON first, then YAML if available
                try:
                    parsed = json.loads(data)
                except json.JSONDecodeError:
                    if yaml is None:
                        raise RuntimeError(f'Unsupported file format and PyYAML not installed: {fname}')
                    parsed = yaml.safe_load(data)
        except Exception as exc:
            error_records.append(create_error_record(exc, fname))
            continue

        # Validate parsed config: placeholder (could add schema checks)
        if not isinstance(parsed, dict):
            error_records.append(
                create_error_record(
                    ValueError(f'Parsed configuration is not a dict in file {fname}'), fname
                )
            )
            continue

        # Apply overrides if provided
        if isinstance(overrides, dict):
            merge_override(parsed, overrides)

        # Resolve environment variables if requested
        if resolve_env:
            try:
                parsed = resolve_env_vars(parsed)
            except Exception as exc:  # pragma: no cover
                error_records.append(create_error_record(exc, fname))

        configs[fname] = parsed

    return configs, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    try:
        import yaml
    except Exception:
        yaml = None
    try:
        import json
    except Exception:
        json = None

    logger = logging.getLogger('config_loader')
    parsed_configs = {}
    error_records = []

    # Ensure config_filenames is an iterable
    if isinstance(config_filenames, (str, bytes)):
        filenames = [config_filenames]
    else:
        filenames = list(config_filenames)

    for fname in filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as fh:
                raw = fh.read()
        except Exception as exc:
            # create LogRecord for the error
            rec = logging.LogRecord(
                name=logger.name,
                level=logging.ERROR,
                pathname=__file__,
                lineno=0,
                msg=f"Failed to read configuration file '{fname}': {exc}",
                args=None,
                exc_info=exc
            )
            error_records.append(rec)
            continue

        # Parse the configuration
        cfg = None
        last_exc = None
        if yaml is not None:
            try:
                cfg = yaml.safe_load(raw)
                last_exc = None
            except Exception as exc:
                last_exc = exc
        if cfg is None and json is not None:
            try:
                cfg = json.loads(raw)
                last_exc = None
            except Exception as exc:
                last_exc = exc
        if cfg is None:
            # cannot parse
            exc = last_exc or ValueError("Unrecognized configuration format")
            rec = logging.LogRecord(
                name=logger.name,
                level=logging.ERROR,
                pathname=__file__,
                lineno=0,
                msg=f"Failed to parse configuration file '{fname}': {exc}",
                args=None,
                exc_info=exc
            )
            error_records.append(rec)
            continue

        # Resolve environment variables if requested
        if resolve_env and isinstance(cfg, dict):
            def _resolve(value):
                if isinstance(value, str):
                    return os.path.expandvars(value)
                elif isinstance(value, dict):
                    return {k: _resolve(v) for k, v in value.items()}
                elif isinstance(value, list):
                    return [_resolve(v) for v in value]
                else:
                    return value
            cfg = _resolve(cfg)

        # Apply overrides if provided
        if overrides:
            if isinstance(overrides, dict):
                # Simple shallow merge
                for k, v in overrides.items():
                    cfg[k] = v
            else:
                # Invalid overrides type
                rec = logging.LogRecord(
                    name=logger.name,
                    level=logging.ERROR,
                    pathname=__file__,
                    lineno=0,
                    msg=f"Overrides for '{fname}' should be a dict but was {type(overrides).__name__}",
                    args=None,
                    exc_info=None
                )
                error_records.append(rec)

        parsed_configs[fname] = cfg

    return parsed_configs, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import re
    import logging

    if isinstance(config_filenames, (str, bytes)):
        config_filenames = [config_filenames]
    configs = {}
    errors = []

    env_pattern = re.compile(r'\$\{([^}]+)\}|\$([A-Za-z0-9_]+)')

    def _resolve_env(value):
        """Recursively resolve environment variables in a value."""
        if isinstance(value, str):
            def repl(m):
                var = m.group(1) or m.group(2)
                return os.getenv(var, '')
            return env_pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: _resolve_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env(v) for v in value]
        else:
            return value

    for fn in config_filenames:
        if not fn:
            err_msg = f"Empty filename supplied."
            errors.append(logging.LogRecord(
                'load_configurations', logging.ERROR, fn, 0, err_msg, (), None))
            continue
        if not os.path.exists(fn):
            err_msg = f"Configuration file '{fn}' does not exist."
            errors.append(logging.LogRecord(
                'load_configurations', logging.ERROR, fn, 0, err_msg, (), None))
            continue
        try:
            with open(fn, 'r', encoding='utf-8') as f:
                content = f.read()
            if not content.strip():
                raise ValueError("Configuration file is empty.")
            data = json.loads(content)
            if not isinstance(data, dict):
                raise ValueError("Configuration must be a JSON object.")
        except Exception as e:
            err_msg = f"Failed to load configuration from '{fn}': {e}"
            errors.append(logging.LogRecord(
                'load_configurations', logging.ERROR, fn, 0, err_msg, (), None))
            continue

        # Apply overrides if provided
        if overrides:
            if isinstance(overrides, dict):
                # merge top‑level overrides into the parsed dict
                for k, v in overrides.items():
                    data[k] = v

        # Resolve environment variables if requested
        if resolve_env:
            data = _resolve_env(data)

        configs[fn] = data

    return configs, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    # normalize input to a list
    if isinstance(config_filenames, (str, bytes)):
        filenames = [config_filenames]
    else:
        try:
            filenames = list(config_filenames)
        except TypeError:
            raise TypeError('config_filenames must be a string or an iterable of strings')

    # Prepare containers for the results
    configurations = {}
    error_records = []

    import json
    import os

    logger_name = __name__

    # Helper to handle environment variable substitution
    def resolve_env_vars(value):
        if isinstance(value, str):
            # Replace ${VAR} or $VAR with environment variable
            import re
            pattern = re.compile(r'\$\{([^}]+)\}|\$([A-Za-z_][A-Za-z0-9_]*)')
            def replace(match):
                var_name = match.group(1) or match.group(2)
                return os.getenv(var_name, '')
            return pattern.sub(replace, value)
        elif isinstance(value, dict):
            return {k: resolve_env_vars(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [resolve_env_vars(v) for v in value]
        else:
            return value

    # Try to import yaml as an optional parsing library
    try:
        import yaml
        yaml_available = True
    except Exception:
        yaml_available = False

    for filename in filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
            # Try to parse JSON first
            try:
                parsed = json.loads(content)
            except json.JSONDecodeError:
                # If json fails, try yaml if available
                if yaml_available:
                    try:
                        parsed = yaml.safe_load(content)
                    except Exception as e:
                        # Unable to parse as yaml either
                        record = logging.Logger.makeRecord(
                            logger_name,
                            logging.ERROR,
                            filename, 0,
                            f'Failed to parse configuration file {filename} as JSON or YAML: {e}',
                            (),
                            exc_info=True
                        )
                        error_records.append(record)
                        continue
                else:
                    record = logging.Logger.makeRecord(
                        logger_name,
                        logging.ERROR,
                        filename, 0,
                        f'Failed to parse configuration file {filename} as JSON and YAML parser not available',
                        (),
                        exc_info=True
                    )
                    error_records.append(record)
                    continue
            # Resolve environment variables if requested
            if resolve_env:
                parsed = resolve_env_vars(parsed)
            # Apply overrides if provided
            if overrides and isinstance(overrides, dict):
                # Simple deep merge
                def deep_merge(d, u):
                    for k, v in u.items():
                        if isinstance(v, dict) and isinstance(d.get(k), dict):
                            deep_merge(d[k], v)
                        else:
                            d[k] = v
                deep_merge(parsed, overrides)
            configurations[filename] = parsed
        except FileNotFoundError as e:
            record = logging.Logger.makeRecord(
                logger_name,
                logging.ERROR,
                filename, 0,
                f'Configuration file not found: {filename}',
                (),
                exc_info=True
            )
            error_records.append(record)
        except Exception as e:
            record = logging.Logger.makeRecord(
                logger_name,
                logging.ERROR,
                filename, 0,
                f'Error loading configuration file {filename}: {e}',
                (),
                exc_info=True
            )
            error_records.append(record)

    return configurations, error_records

