    if curr_scale is None or curr_scale == 0:
        raise LenaValueError("Cannot rescale graph with unknown or zero scale")

    # Determine the scaling factor
    factor = other / curr_scale

    # Attempt to rescale data points – only the last coordinate
    fields = getattr(self, "fields", None)
    if fields and isinstance(fields, (list, tuple)):
        last_index = len(fields) - 1
        data = getattr(self, "_data", None)
        if data and hasattr(data, "__iter__"):
