                # left is index 0, right 1, middle 2 convention
                mapping = {"left": 0, "right": 1, "middle": 2}
                idx = mapping.get(get_coordinate)
                if idx is not None and isinstance(bin_obj, (list, tuple)):
                    return bin_obj[idx]
            except Exception:
                pass
        # fallback: try numeric attribute
        try:
