def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    # D* nodes typically expect timestamps in ISO 8601 format,
    # using ``YYYY-MM-DDThh:mm:ssZ`` for UTC or
    # ``YYYY-MM-DDThh:mm:ss+/-hh:mm`` for timezone-aware datetimes.
    # For dates only, ``YYYY-MM-DD`` is sufficient.
    if dt is None:
        return None

    try:
        # Strings are returned unchanged, assuming they are already formatted
        if isinstance(dt, str):
            return dt

        # Handle datetime objects (aware or naive)
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                # Naive datetimes are treated as UTC
                return dt.strftime('%Y-%m-%dT%H:%M:%SZ')
            else:
                # ISO 8601 representation handles offsets
                return dt.isoformat()

        # Handle date objects
        if isinstance(dt, datetime.date):
            return dt.isoformat()

        raise TypeError(f"Unsupported type for format_dt: {type(dt).__name__}")

    except Exception as exc:
        # Wrap any unexpected error in a ValueError to keep the API consistent
        raise ValueError(f"Could not format datetime {dt!r}") from exc

