def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re
    tags: Set[str] = set()

    # Find all code blocks (```` ... ````) and inline code (` ... `)
    code_intervals: list[tuple[int, int]] = []

    # Triple-backtick blocks
    for m in re.finditer(r'```.*?```', text, flags=re.S):
        code_intervals.append((m.start(), m.end()))

    # Inline backticks
    for m in re.finditer(r'`[^`]*`', text, flags=re.S):
        code_intervals.append((m.start(), m.end()))

    # Merge overlapping intervals for efficiency
    if code_intervals:
        code_intervals.sort()
        merged: list[tuple[int, int]] = [code_intervals[0]]
        for start, end in code_intervals[1:]:
            last_start, last_end = merged[-1]
            if start <= last_end:  # overlap
                merged[-1] = (last_start, max(last_end, end))
            else:
                merged.append((start, end))
        code_intervals = merged

    def _inside_code(pos: int) -> bool:
        for start, end in code_intervals:
            if start <= pos < end:
                return True
        return False

    # Function to replace tags outside code blocks
    def replace_tag(match: re.Match) -> str:
        pos = match.start()
        if _inside_code(pos):
            return match.group()
        tag = match.group()[1:]  # strip leading '#'
        tags.add(tag)
        if replacer is not None:
            try:
                return replacer(tag)
            except Exception:  # pragma: no cover
                # Fall back to original tag if replacer fails
                return match.group()
        return match.group()

    # Perform substitution
    pattern = r'\B#\w+'
    replaced_text = re.sub(pattern, replace_tag, text)

    return tags, replaced_text

