def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload. However, the sender might
    be trying to set another author in the payload itself, since Diaspora has the sender in both the payload headers
    AND the object. We must ensure they're the same.
    """
    # Handles must be provided; missing value is treated as an error
    if sender_handle is None or entity_handle is None:
        raise ValueError(f"Sender handle and entity handle must be provided; got sender={sender_handle!r}, entity={entity_handle!r}")

    # Normalise to stripped strings
    try:
        normal_sender = str(sender_handle).strip()
        normal_entity = str(entity_handle).strip()
    except Exception as exc:
        raise ValueError(f"Error converting handles to strings: {exc}") from exc

    if normal_sender != normal_entity:
        raise ValueError(
            f"Sender and entity handles do not match: sender={normal_sender!r}, entity={normal_entity!r}"
        )

    return True

def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload. However, the sender
    might be trying to set another author in the payload itself, since Diaspora has the sender in both the
    payload headers AND the object. We must ensure they're the same.
    """
    # Helper to extract a comparable handle value
    def _to_handle(val):
        if val is None:
            return None
        # Common cases: dictionary with a handle key
        if isinstance(val, dict):
            for key in ("handle", "username", "id", "author"):
                if key in val:
                    return val[key]
        # Objects with a handle attribute
        if hasattr(val, "handle"):
            return val.handle
        if hasattr(val, "username"):
            return val.username
        try:
            return str(val)
        except Exception:
            return None

    sender_val = _to_handle(sender_handle)
    entity_val = _to_handle(entity_handle)

    if sender_val is None or entity_val is None:
        raise ValueError("Both sender_handle and entity_handle must be provided and "
                         "extractable to comparable values")

    if sender_val != entity_val:
        raise ValueError(f"Sender handle '{sender_val}' does not match entity handle '{entity_val}'")

    return True

