def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    import base64
    import pathlib
    from xml.etree import ElementTree as ET

    # Resolve the public key object
    try:
        if isinstance(public_key, (bytes, str)):
            # If a path is given
            if isinstance(public_key, str) and pathlib.Path(public_key).exists():
                pem_data = pathlib.Path(public_key).read_bytes()
            else:
                pem_data = public_key if isinstance(public_key, bytes) else public_key.encode("utf-8")
            # Load the key using cryptography
            from cryptography.hazmat.primitives import serialization
            key = serialization.load_pem_public_key(pem_data)
        elif hasattr(public_key, "verify"):
            key = public_key
        else:
            raise TypeError("public_key must be a PEM string, path to a PEM file, or a key object")
    except Exception as exc:
        raise ValueError("Failed to parse public key") from exc

    # Ensure the document is an Element
    if isinstance(doc, str):
        try:
            doc = ET.fromstring(doc)
        except Exception as exc:
            raise ValueError("doc string could not be parsed as XML") from exc
    if not hasattr(doc, "tag"):
        raise ValueError("doc must be an ElementTree Element or XML string")

    # Canonicalise the XML (simple string conversion)
    try:
        xml_bytes = ET.tostring(doc, encoding="utf-8", method="xml")
    except Exception as exc:
        raise ValueError("Failed to serialize XML for verification") from exc

    # Decode the Base64 signature
    try:
        sig_bytes = base64.b64decode(signature)
    except Exception as exc:
        raise ValueError("Signature is not valid Base64") from exc

    # Verify the signature
    try:
        from cryptography.hazmat.primitives import hashes
        from cryptography.hazmat.primitives.asymmetric import padding
        from cryptography.exceptions import InvalidSignature

        key.verify(
            sig_bytes,
            xml_bytes,
            padding.PKCS1v15(),
            hashes.SHA256()
        )
        return True
    except InvalidSignature:
        return False
    except Exception as exc:
        # Any other cryptographic error is treated as a verification failure
        return False

