def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Try to parse as JSON first
    try:
        import json
        data = json.loads(document)
        if isinstance(data, dict) and 'subject' in data:
            return data
    except Exception:
        pass

    # Try to parse as XRD (XML)
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)

        ns = {'xrd': root.tag.split('}')[0].strip('{')} if '}' in root.tag else {}

        def find_tag(tag, namespace=None):
            return root.find(f"{{{namespace}}}{tag}") if namespace else root.find(tag)

        def findall_tag(tag, namespace=None):
            return root.findall(f"{{{namespace}}}{tag}") if namespace else root.findall(tag)

        subject_elem = find_tag('subject', ns.get('xrd'))
        subject = subject_elem.text.strip() if subject_elem is not None and subject_elem.text else None

        alias_elems = findall_tag('alias', ns.get('xrd'))
        aliases = [ae.text.strip() for ae in alias_elems if ae is not None and ae.text] if alias_elems else []

        links = []
        link_elems = findall_tag('link', ns.get('xrd'))
        for le in link_elems:
            link_info = {}
            # Attributes
            for attr in ['rel', 'type', 'href', 'template', 'title', 'media_type', 'digest', 'rel', 'type', 'href', 'template']:
                if attr in le.attrib:
                    link_info[attr] = le.attrib[attr]
            # Child elements
            for child in le:
                if child.tag.endswith('rel') and child.text:
                    link_info['rel'] = child.text.strip()
                elif child.tag.endswith('type') and child.text:
                    link_info['type'] = child.text.strip()
                elif child.tag.endswith('href') and child.text:
                    link_info['href'] = child.text.strip()
                elif child.tag.endswith('template') and child.text:
                    link_info['template'] = child.text.strip()
                elif child.tag.endswith('title') and child.text:
                    link_info['title'] = child.text.strip()
            links.append(link_info)

        result = {
            'subject': subject,
            'aliases': aliases,
            'links': links,
        }
        return result
    except Exception:
        # If parsing fails, return empty dict
        return {}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    result: Dict = {}
