    def _tag_name(tag: str) -> str:
        return tag.split('}')[-1] if '}' in tag else tag

    subject = None
    aliases: list[str] = []
    links: list[dict] = []

    for elem in root.iter():
        tag = _tag_name(elem.tag)
        if tag == 'Subject' and elem.text:
