            rel = elem.attrib.get('rel')
            href = elem.attrib.get('href')
            type_ = elem.attrib.get('type')
            if rel:
                link['rel'] = rel
            if href:
                link['href'] = href
            if type_:
                link['type'] = type_
            if link:
                links.append(link)

    result = {
        'subject': subject,
        'aliases': aliases,
        'links': links
    }
    return result

