def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Basic type checks
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Retrieve the list of deprecated arguments; fall back to empty list if not defined
    deprecated = getattr(self, "deprecated_args", [])
    if not isinstance(deprecated, (list, set, tuple)):
        deprecated = list(deprecated)

    # Collect any deprecated arguments found in either dict
    found = []
    for src, args in (("cli", cli_args), ("answer_file", answer_file_args)):
        for key in args:
            if key in deprecated:
                found.append(f"{src} argument '{key}'")

    # If any were found, produce a readable warning
    if found:
        warning_msg = "Deprecated arguments used: " + ", ".join(found)
        try:
            # Prefer warnings module if available, otherwise fall back to print
            import warnings
            warnings.warn(warning_msg, DeprecationWarning, stacklevel=3)
        except Exception:
            # If any issue importing warnings, just print
            print(warning_msg)

