def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
        """
        # If the class does not define any length limits, nothing to validate.
        length_specs = getattr(self, "LENGTHS", None)
        if not length_specs:
            return

        # Normalize arguments to a mapping of name->value.
        if isinstance(args, dict):
            arg_items = args.items()
        else:
            # For sequences (e.g. list/tuple) we map to the order implied by LENGTHS
            # If LENGTHS is a dict, we respect its keys in that order.
            # If LENGTHS is a list/tuple, we use that order.
            if isinstance(length_specs, dict):
                keys = list(length_specs.keys())
            else:
                keys = range(min(len(args), len(length_specs)))
            arg_items = zip(keys, args)

        for name, value in arg_items:
            # Skip keys that don't have a defined limit.
            try:
                max_len = length_specs[name]
            except (KeyError, IndexError, TypeError):
                continue

            # Determine the actual length of the value.
            try:
                val_len = len(value)
            except (TypeError, AttributeError):
                try:
                    val_len = len(str(value))
                except Exception:
                    # If we cannot determine a length, skip validation for this item.
                    continue

            if val_len > max_len:
                raise ValueError(
                    f"Argument '{name}' length {val_len} exceeds maximum allowed {max_len}."
