    max_lengths = getattr(self, "max_lengths", None) or \
                  getattr(self, "_max_lengths", None) or \
                  getattr(self.__class__, "max_lengths", None) or \
                  getattr(self.__class__, "_max_lengths", None)

    if max_lengths is None:
        # No length restrictions defined; nothing to check
        return

    # Helper to validate a single value against its expected maximum length
    def _check_length(name_or_index, value, expected):
        if expected is None or expected <= 0:
            return
        try:
            length = len(value)
        except Exception:
            # Non-lengthable objects are ignored
            return
        if length > expected:
            raise ValueError(
                f"Argument '{name_or_index}' has length {length}, "
                f"which exceeds the maximum allowed {expected}"
            )

    if isinstance(args, dict):
        for key, value in args.items():
            expected = max_lengths.get(key) if isinstance(max_lengths, dict) else None
            _check_length(key, value, expected)
    else:  # list or tuple
        if isinstance(max_lengths, (list, tuple)):
            for idx, value in enumerate(args):
                if idx >= len(max_lengths):
                    break
                expected = max_lengths[idx]
                _check_length(idx, value, expected)

