                                    spec_option):
        """Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
        # Validate basic input
        if not isinstance(subcommand, str):
            raise TypeError("subcommand must be a string")
        if not isinstance(type_name, str):
            raise TypeError("type_name must be a string")
        if not isinstance(option_name, str):
            raise TypeError("option_name must be a string")
        if not isinstance(spec_option, dict):
            raise TypeError("spec_option must be a dict")

        # Helper to safely obtain the datatype callable
        def _get_datatype(dt):
            if isinstance(dt, str):
                mapping = {"int": int, "float": float, "str": str}
                if dt in mapping:
                    return mapping[dt]
                # Allow built-in types by name only
                if dt in ("bool", "bytes", "list", "dict"):
                    return eval(dt)
                raise ValueError(f"Unsupported datatype string: '{dt}'")
            if callable(dt):
                return dt
            raise TypeError(f"datatype must be a string or callable, got {type(dt)}")

        delimiter = spec_option.get("delimiter", ",")
        if not isinstance(delimiter, str):
            raise TypeError("delimiter in spec_option must be a string")

        datatype_spec = spec_option.get("datatype", "str")
        datatype_func = _get_datatype(datatype_spec)

        required = spec_option.get("required", False)
        if not isinstance(required, bool):
            raise TypeError("required flag must be boolean")

        def _parser(value):
            """
            Parse a string value into a list of typed items based on the
            configuration supplied to this method.
            """
            if required and (value is None or value == ""):
                raise ValueError(
                    f"Option '{option_name}' for subcommand '{subcommand}' "
                    f"cannot be empty (required=True)."
                )
            # If no value provided and not required, return empty list
            if value is None or value == "":
                return []
            try:
                parts = [p.strip() for p in value.split(delimiter)]
                # Filter out empty strings that may arise from consecutive delimiters
                parts = [p for p in parts if p != ""]
                return [datatype_func(p) for p in parts]
            except Exception as exc:
                raise ValueError(
                    f"Error parsing option '{option_name}' for subcommand "
                    f"'{subcommand}': {exc}"
                ) from exc

        # Attach metadata to the parser function for downstream tools if needed
        _parser.__name__ = f"{type_name}_{option_name}_parser"
        _parser.__doc__ = (
            f"Parser for complex option '{option_name}' on subcommand '{subcommand}'. "
            f"Splits input on '{delimiter}' and casts to '{datatype_spec}'."
        )
        _parser.delimiter = delimiter
        _parser.datatype = datatype_func
        _parser.required = required
        return _parser

