def extend_cli(self, root_subparsers):
    """Adds the spec cli options to the main entry point."""
    if root_subparsers is None:
        raise ValueError("root_subparsers cannot be None")

    # Ensure that root_subparsers behaves like argparse's _SubParsersAction
    try:
        add_parser = root_subparsers.add_parser
    except AttributeError as exc:
        raise TypeError(
            "root_subparsers must support an 'add_parser' method (e.g., argparse._SubParsersAction)"
        ) from exc

    # Determine the name of the subparser; fall back to the class name if not provided
    parser_name = getattr(self, "name", self.__class__.__name__).lower()
    # Use a description if available
    parser_help = getattr(self, "description", f"{parser_name} command")

    # Create the subparser
    try:
        subparser = add_parser(parser_name, help=parser_help)
    except Exception as exc:
        raise RuntimeError(f"Failed to create subparser '{parser_name}': {exc}") from exc

    # Add CLI options defined on the object. We expect a mapping of option -> config dict.
    cli_opts = getattr(self, "cli_options", {})
    if not isinstance(cli_opts, dict):
        raise ValueError("Attribute 'cli_options' must be a dictionary mapping option names to configuration dictionaries")

    for opt, config in cli_opts.items():
        if not isinstance(opt, str):
            raise ValueError(f"Option names must be strings, got {opt!r}")
        if not isinstance(config, dict):
            raise ValueError(f"Configuration for option {opt!r} must be a dictionary")

        # Extract common argument parameters
        help_text = config.get("help", "")
        action = config.get("action")
        nargs = config.get("nargs")
        type_ = config.get("type")
        default = config.get("default")

        # Build keyword arguments for add_argument
        kwargs = {"help": help_text}
        if action:
            kwargs["action"] = action
        if nargs:
            kwargs["nargs"] = nargs
        if type_:
            kwargs["type"] = type_
        if default is not None:
            kwargs["default"] = default

        try:
            subparser.add_argument(opt, **kwargs)
        except Exception as exc:
            raise RuntimeError(f"Failed to add argument {opt!r}: {exc}") from exc

    return subparser

