def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if root is None or root == '':
        raise ValueError("root must not be empty")
    norm_path = os.path.normpath(path)
    norm_root = os.path.normpath(root)

    # If the path is exactly the root, return an empty string
    if norm_path == norm_root:
        return ''

    # Ensure the path starts with the root
    try:
        # os.path.commonpath will raise ValueError for mixed user- and system- paths
        common = os.path.commonpath([norm_path, norm_root])
    except ValueError as exc:
        raise ValueError(f"Unable to determine common root: {exc}")

    if common != norm_root:
        raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")

    # Compute relative path
    rel = os.path.relpath(norm_path, norm_root)

    # relpath may return '.' or starts with '..' if path is above root – treat those as errors
    if rel == '.':
        return ''
    if rel.startswith(os.pardir) or os.path.isabs(rel):
        raise ValueError(f"Cannot strip root: resulting relative path '{rel}'")
    return rel

